func newIAMTagRoleCmd() *cobra.Command {
	var roleName string
	var tags []string

	cmd := &cobra.Command{
		Use:   "tag-role",
		Short: "TagRole",
		RunE: func(cmd *cobra.Command, _ []string) error {
			cfg, err := newAWSConfig(cmd.Context())
			if err != nil {
				return err
			}

			client := iam.NewFromConfig(cfg, func(o *iam.Options) {
				o.BaseEndpoint = aws.String(endpointURL)
			})

			input := &iam.TagRoleInput{}

			if roleName != "" {
				input.RoleName = aws.String(roleName)
			}

			for _, raw := range tags {
				var val types.Tag
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), raw); err != nil {
					return fmt.Errorf("tag-role: parse --tags: %w", err)
				}
				input.Tags = append(input.Tags, val)
			}

			_, err = client.TagRole(cmd.Context(), input)
			if err != nil {
				return fmt.Errorf("tag-role failed: %w", err)
			}

			return nil
		},
	}

	cmd.Flags().StringVar(&roleName, "role-name", "", "Role name")

	cmd.Flags().StringArrayVar(&tags, "tags", nil, "Tags (key=value,key2=value2, repeatable)")

	cmd.Flags().String("region", "", "Region override (ignored)")

	return cmd
}

